on conflict do nothing;

do $$
declare
  v_app uuid;
begin
  if not exists (select 1 from core.organizations where id = 'mirea') then
    return;
  end if;

    organization_id, owner_id, slug, name, description,
    icon_emoji, accent_color, category, tags, requested_permissions,
    source_kind, status, published_at
  )
  values (
    'mirea', null, 'showcase', 'Витрина возможностей', 'Демо мини-апп в стиле дизайн-системы: кнопки, ввод, выбор, обратная связь, поверхности, списки, календарь, логика и действия платформы.',
    '🎛️', '#8064FF', 'tools', array['демо','виджеты','showcase','примеры','ui kit'], array['location','camera','files','calendar'],
    'hosted', 'published', now()
  )
  on conflict (organization_id, slug) do update set
    name = excluded.name,
    description = excluded.description,
    icon_emoji = excluded.icon_emoji,
    accent_color = excluded.accent_color,
    category = excluded.category,
    tags = excluded.tags,
    requested_permissions = excluded.requested_permissions,
    status = 'published',
    updated_at = now()
  returning id into v_app;

  delete from core.mini_app_screens where app_id = v_app;
end $$;
